{
  "preprint_doi": "10.1101/2024.05.03.24306688",
  "version": "v2",
  "claims": [
    {
      "section": "abstract",
      "claim_idx": 0,
      "text": "Amblyopia is a neurodevelopmental visual disorder that affects approximately 3-5% of children globally and it can lead to vision loss if it is not diagnosed and treated early.",
      "claim_type": "hedged",
      "hedging_level": "weak",
      "numerical_values": [
        {
          "metric": "prevalence",
          "value": 3,
          "unit": "%",
          "comparison": "absolute"
        },
        {
          "metric": "prevalence",
          "value": 5,
          "unit": "%",
          "comparison": "absolute"
        }
      ]
    },
    {
      "section": "abstract",
      "claim_idx": 1,
      "text": "Traditional diagnostic methods, which rely on subjective assessments and expert interpretation of eye movement recordings presents challenges in resource-limited eye care centers.",
      "claim_type": "qualitative",
      "hedging_level": "none",
      "numerical_values": []
    },
    {
      "section": "abstract",
      "claim_idx": 3,
      "text": "LLMs can be successfully applied to the analysis of fixation eye movement data to diagnose patients with amblyopia.",
      "claim_type": "hedged",
      "hedging_level": "weak",
      "numerical_values": []
    },
    {
      "section": "abstract",
      "claim_idx": 3,
      "text": "Input of medical subject matter expertise, introduced in this study in the form of medical expert augmented generation (MEAG), is an effective adaption of the generic retrieval augmented generation (RAG) approach for medical applications using LLMs.",
      "claim_type": "qualitative",
      "hedging_level": "none",
      "numerical_values": []
    },
    {
      "section": "abstract",
      "claim_idx": 4,
      "text": "This study introduces a new multi-view prompting framework for ophthalmology applications that incorporates fine granularity feedback from pediatric ophthalmologist together with in-context learning to report an accuracy of 80% in diagnosing patients with amblyopia.",
      "claim_type": "quantitative",
      "hedging_level": "none",
      "numerical_values": [
        {
          "metric": "accuracy",
          "value": 80,
          "unit": "%",
          "comparison": "absolute"
        }
      ]
    },
    {
      "section": "abstract",
      "claim_idx": 5,
      "text": "In addition to the binary classification task, the classification tool is generalizable to specific subpopulations of amblyopic patients based on severity of amblyopia, type of amblyopia, and with or without nystagmus.",
      "claim_type": "qualitative",
      "hedging_level": "none",
      "numerical_values": []
    },
    {
      "section": "abstract",
      "claim_idx": 6,
      "text": "The model reports an accuracy of: (1) 83% in classifying patients with moderate or severe amblyopia",
      "claim_type": "quantitative",
      "hedging_level": "none",
      "numerical_values": [
        {
          "metric": "accuracy",
          "value": 83,
          "unit": "%",
          "comparison": "absolute"
        }
      ]
    },
    {
      "section": "abstract",
      "claim_idx": 6,
      "text": "(2) 81% in classifying patients with mild or treated amblyopia",
      "claim_type": "quantitative",
      "hedging_level": "none",
      "numerical_values": [
        {
          "metric": "accuracy",
          "value": 81,
          "unit": "%",
          "comparison": "absolute"
        }
      ]
    },
    {
      "section": "abstract",
      "claim_idx": 6,
      "text": "and (3) 85% accuracy in classifying patients with nystagmus.",
      "claim_type": "quantitative",
      "hedging_level": "none",
      "numerical_values": [
        {
          "metric": "accuracy",
          "value": 85,
          "unit": "%",
          "comparison": "absolute"
        }
      ]
    },
    {
      "section": "abstract",
      "claim_idx": 7,
      "text": "To the best of our knowledge, this is the first study that defines a multiview prompting framework with MEAG to analyze eye tracking data for the diagnosis of amblyopic patients.",
      "claim_type": "qualitative",
      "hedging_level": "weak",
      "numerical_values": []
    }
  ],
